const types = [
  "click",
  "dblclick",
  "input",
  "change",
  "keydown",
  "keyup",
  "mouseover",
  "mouseout",
  "mouseenter",
  "mouseleave",
  "focus",
  "blur",
  "focusin",
  "focusout",
  "pointerdown",
  "pointerup",
];
const rows = [];
for (const selector of ["#input", "#area", "#button"]) {
  const node = document.querySelector(selector);
  for (const type of types)
    node.addEventListener(type, (event) => {
      rows.push(
        event.type +
          " target=" +
          event.target.tagName +
          " current=" +
          event.currentTarget.tagName +
          " key=" +
          event.key +
          " code=" +
          event.code,
      );
      document.querySelector("#events").textContent = rows
        .slice(-12)
        .join("\n");
    });
}

const out = document.querySelector("#events");
function record(label, event) {
  const li = document.createElement("li");
  li.textContent =
    label +
    " phase=" +
    event.eventPhase +
    " target=" +
    event.target.id +
    " current=" +
    event.currentTarget.id;
  out.append(li);
}
for (const id of ["outer", "inner"]) {
  const node = document.getElementById(id);
  node.addEventListener(
    "click",
    (e) => {
      if (id === "outer") out.replaceChildren();
      record(id + " capture", e);
    },
    true,
  );
  node.addEventListener("click", (e) => {
    record(id + " bubble", e);
    if (id === "inner") {
      const mode = document.querySelector("#stop").value;
      if (mode === "propagation") e.stopPropagation();
      if (mode === "immediate") e.stopImmediatePropagation();
    }
  });
}
document
  .querySelector("#inner")
  .addEventListener("click", (e) => record("inner second listener", e));
document
  .querySelector("#target")
  .addEventListener("click", (e) => record("target listener", e));

