function validate() {
  const email = document.querySelector("#email"),
    a = document.querySelector("#first"),
    b = document.querySelector("#second");
  const emailError = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())
    ? ""
    : "Enter a plausible fictional email.";
  const confirmError =
    a.value.length < 8
      ? "Use at least eight fictional characters."
      : a.value !== b.value
        ? "The two strings must match."
        : "";
  document.querySelector("#email-error").textContent = emailError;
  document.querySelector("#confirm-error").textContent = confirmError;
  email.setAttribute("aria-invalid", String(!!emailError));
  b.setAttribute("aria-invalid", String(!!confirmError));
  return !emailError && !confirmError;
}
