let timer = null,
  ticker = null,
  started = 0,
  remaining = 0,
  elapsed = 0;
const state = document.querySelector("#state");
function cancel() {
  clearTimeout(timer);
  clearInterval(ticker);
  timer = ticker = null;
}
function arm() {
  started = performance.now();
  state.textContent = "Callback pending: " + Math.round(remaining) + " ms";
  timer = setTimeout(() => {
    elapsed += performance.now() - started;
    cancel();
    remaining = 0;
    state.textContent = "Callback executed";
    console.log("Actual callback after", Math.round(elapsed), "ms");
  }, remaining);
  ticker = setInterval(() => {
    document.querySelector("#elapsed").textContent =
      "Elapsed " +
      Math.round(elapsed + performance.now() - started) +
      " ms";
  }, 50);
}
