document.querySelector("#load").addEventListener("click", async () => {
  const wait = (value, ms, fail = false) =>
    new Promise((resolve, reject) =>
      setTimeout(() => (fail ? reject(Error(value)) : resolve(value)), ms),
    );
  const results = await Promise.allSettled([
    wait("A", 20),
    wait("B failed", 10, true),
  ]);
  console.log(results.map((r) => r.status));
  try {
    await Promise.race([
      wait("slow success", 40),
      wait("fast failure", 10, true),
    ]);
  } catch (error) {
    console.log("race:", error.message);
  }
  console.log(
    "any:",
    await Promise.any([
      wait("failure", 10, true),
      wait("first success", 30),
    ]),
  );
  const controller = new AbortController();
  let attempts = 0;
  try {
    for (let attempt = 0; attempt < 2; attempt++) {
      attempts++;
      try {
        const response = await fetch("/api/students", {
          signal: controller.signal,
        });
        if (!response.ok) throw Error("HTTP " + response.status);
        const rows = await response.json();
        document.querySelector("#out").textContent =
          rows.length + " rows after " + attempts + " attempt(s)";
        break;
      } catch (error) {
        if (error.name === "AbortError" || attempt === 1) throw error;
        await wait(null, 50);
      }
    }
  } catch (error) {
    document.querySelector("#out").textContent = error.message;
  } finally {
    controller.abort();
    console.log("cleanup complete");
  }
});

